fn check_if_last_char_is_a_letter(txt: &str) -> bool {
    // Check if the string is non-empty
    if txt.is_empty() {
        return false;
    }

    // Get the last character
    let last_char = txt.chars().last().unwrap();

    // Check if the last character is an ASCII letter
    if !last_char.is_ascii_alphabetic() {
        return false;
    }

    // Check if the string has exactly one character or the character before the last is a space
    if txt.len() == 1 {
        return true;
    }

    // Get the character before the last character
    let second_last_char = txt.chars().nth(txt.len() - 2).unwrap();
    
    // Return true if the second last character is a space
    second_last_char == ' '
}

fn main() {
    // Test cases
    println!("{}", check_if_last_char_is_a_letter("Hello ")); // true
    println!("{}", check_if_last_char_is_a_letter("Hello"));  // true
    println!("{}", check_if_last_char_is_a_letter("Hello!")); // false
    println!("{}", check_if_last_char_is_a_letter(" "));      // false
    println!("{}", check_if_last_char_is_a_letter("A"));      // true
    println!("{}", check_if_last_char_is_a_letter("A "));     // true
    println!("{}", check_if_last_char_is_a_letter(""));       // false
}